// Photographic yarn cropped from the AFTER rope. Width crosses a ply; height runs along it.

export const YARN_W = 66;
export const YARN_H = 606;

const YARN_B64 =
  "";

let yarnRgb: Uint8Array | null = null;

function yarnRgbBytes() {
  if (yarnRgb) return yarnRgb;
  const bin = atob(YARN_B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  yarnRgb = out;
  return out;
}

function wrapIndex(i: number, n: number) {
  return ((i % n) + n) % n;
}

export function yarnSample(u: number, v: number): [number, number, number] {
  const data = yarnRgbBytes();
  let fu = u % 1;
  if (fu < 0) fu += 1;
  let fv = v % 1;
  if (fv < 0) fv += 1;
  const x = fu * YARN_W - 0.5;
  const y = fv * YARN_H - 0.5;
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const tx = x - x0;
  const ty = y - y0;
  const at = (ix: number, iy: number, channel: number) =>
    data[(wrapIndex(iy, YARN_H) * YARN_W + wrapIndex(ix, YARN_W)) * 3 + channel];
  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const channels: [number, number, number] = [0, 0, 0];
  for (let channel = 0; channel < 3; channel++) {
    const top = lerp(at(x0, y0, channel), at(x0 + 1, y0, channel), tx);
    const bottom = lerp(at(x0, y0 + 1, channel), at(x0 + 1, y0 + 1, channel), tx);
    channels[channel] = lerp(top, bottom, ty);
  }
  return channels;
}
